package com.spaceagent.platform.runtime.domain;
import java.util.Objects;
/** Pure rollout/fallback decision. Unknown effects never select another Supervisor policy. */
public record SupervisorPolicyResolution(SupervisorPolicy policy,Outcome outcome){public enum Outcome{SELECTED,FORCED_DETERMINISTIC,UNKNOWN_BLOCKED,INVALID_BLOCKED}public SupervisorPolicyResolution{policy=Objects.requireNonNull(policy);outcome=Objects.requireNonNull(outcome);}public static SupervisorPolicyResolution forNewRun(SupervisorPolicy requested,boolean globalKillSwitch,boolean unknownOrInvalid){if(unknownOrInvalid)return new SupervisorPolicyResolution(deterministic(requested),Outcome.UNKNOWN_BLOCKED);if(globalKillSwitch||requested.killSwitch())return new SupervisorPolicyResolution(deterministic(requested),Outcome.FORCED_DETERMINISTIC);return new SupervisorPolicyResolution(requested,Outcome.SELECTED);}public static SupervisorPolicyResolution forRunningRun(SupervisorPolicy pinned,boolean unknownOrInvalid){return unknownOrInvalid?new SupervisorPolicyResolution(pinned,Outcome.UNKNOWN_BLOCKED):new SupervisorPolicyResolution(pinned,Outcome.SELECTED);}private static SupervisorPolicy deterministic(SupervisorPolicy p){return new SupervisorPolicy(SupervisorPolicyMode.DETERMINISTIC,true,false,p.policyHash(),p.pinnedAt());}}
